export type IconName = keyof typeof icons
export function iconViewBox(name: string) {
    if (name === "doc-spark") return "0 0 16 16"
    if (name === "doc-copy") return "0 0 16 16"
    if (name === "trash-16-fill") return "0 0 16 16"
    if (name === "chevron-down-14") return "0 0 14 14"
    if (name === "multi-user") return "0 0 16 16"
    if (name === "code-slash-16") return "0 0 16 16"
    if (name === "board") return "0 0 16 16"
    if (name === "expert") return "0 0 20 20"
    if (name === "collab") return "0 0 24 24"
    if (["book-open", "brain", "console", "pencil-line"].includes(name)) return "0 0 20 20"
    if (name === "globe") return "0 0 15 15"
    if (["submit-upload", "test-flask", "debug"].includes(name)) return "0 0 18 18"
    if (name === "trash-fill") return "0 0 14 15"
    if (["arrow-down-12"].includes(name)) return "0 0 12 12"
    if (["remove-file", "action-success", "check-error", "chevron-up", "tool-arrow-right", "action-failed", "action-in-progress", "user", "cloud", "unarchive", "close-small-fill", "arrow-up-to-line"].includes(name)) return "0 0 14 14"
    if (["chevron-right-round", "chevron-left-round", "app-prototype", "brain-24", "book-open-24", "plugin-24", "square-code-24", "edit-24", "find-catalog-24", "dialog-box-24", "web-search-24"].includes(name)) return "0 0 24 24"
    if (["save-doc", "expand-message", "collapse-message", "warning-triangle", "folder-plus-24", "export", "delete", "memory", "session-files", "wiki", "eye", "code-slash", "edit", "plus-dialog", "share", "recognition-image", "lightning-charge", "deep-thinking", "level"].includes(name)) return "0 0 24 24"
    if (name === "skill-bolt") return "0 0 15 15"
    if (name === "app-cosmic") return "0 0 16 16"
    if (['dev', 'work', 'chat', "play-circle", "play-triangle", "ai-partner", "app-grid", "arrow-up", "refresh-circle", "mcp", "circle-ban-sign", "circle-x", "stop", "plus", "plus-small", "dash", "dot-grid", "info", "info-fill", "square-arrow-top-right", "bubble-5", "close", "arrow-down-to-line", "circle-check", "circle-x", "plus-dialog", "trash", "close-small", "arrow-left", "chevron-down", "chevron-left", "chevron-right", "warning-circle", "open-file", "undo", "magnifying-glass-menu", "folder", "branch", "fork", "cloud-upload", "help", "paperclip", "cube", "settings-gear", "archive", "bubble-20", "models"].includes(name)) return "0 0 20 20"
    if (["at"].includes(name)) return "0 0 19 19"
    if (name === "close-fill") return "0 0 17 17"
    if (name === "empty-box") return "0 0 56 56"
    if (name === "plus-fill") return "0 0 11 11"
    if (name === "remove-dialog") return "0 0 20 20"
    if (name === 'building') return "0 0 14 14"
    if (name === "loading") return "0 0 48 49"
    return "0 0 16 16"
}
